def assert_repaired_spelling(case, result, expected, msg=None):
    expected=(expected,) if isinstance(expected,str) else tuple(expected)
    actual=result['corrected']
    if result['original'] in expected:
        case.assertEqual(actual,result['original'],msg)
        return
    accepted=tuple(dict.fromkeys(value for old in expected
        for value in (old,)+_REVIEWED.get(old,())))
    assert_reviewed_source_spelling(case,actual,accepted,msg)

