def assert_reviewed_source_spelling(case, actual, expected, msg=None):
    choices=(expected,) if isinstance(expected,str) else tuple(expected)
    accepted=tuple(dict.fromkeys(face for old in choices
        for face in (old,)+_REVIEWED_SOURCE_SPELLINGS.get(old,())))
    case.assertIn(actual,accepted,msg)


def assert_reviewed_result_spelling(case, result, expected, msg=None):
    choices=(expected,) if isinstance(expected,str) else tuple(expected)
    accepted=tuple(dict.fromkeys(face for old in choices for face in (old,)+_REVIEWED.get(old,())))
    assert_reviewed_source_spelling(case,result['corrected'],accepted,msg)


